Конфликт разобран: обе стороны дополняют друг друга (HEAD — рантайм препятствий/опасностей, входящая ветка — частицы и звук). Применяю объединение.

```json
{"version":1,"taskId":"ff44d951-95f0-456f-9081-04f86c5eacd4","commandId":"resolve-1","operation":"run","headSha":"e1fce954743cc27101c89a1c87e83f395570f13c","command":"python3 - <<'PY'
import re
p='src/game/Game.ts'
s=open(p,encoding='utf-8').read()
pat=re.compile(r'<<<<<<< HEAD\n(.*?)\n=======\n(.*?)\n>>>>>>> [0-9a-f]+\n', re.S)
blocks=pat.findall(s)
assert len(blocks)==2, len(blocks)
res1="""    const impact = { ...this.ball.position };
    const safe = this.holeSystem.getLastSafePosition(playerId, this.hole.spawn);
    const resolution = this.runtime?.resolveHazard(hazard, safe) ?? { resetPosition: safe, penaltyStrokes: 1 };
    this.ball.reset(resolution.resetPosition);
    this.runtime?.resetObstacles();
    this.effects.hazard(impact, hazard?.type ?? 'void');
    this.previousVelocity = undefined;
"""
res2=blocks[1][0]+'\n  }\n\n'+blocks[1][1]+'\n'
it=iter([res1,res2])
s=pat.sub(lambda m: next(it), s)
open(p,'w',encoding='utf-8').write(s)
PY
grep -c '<<<<<<<\|>>>>>>>' src/game/Game.ts; sed -n '500,535p;570,615p' src/game/Game.ts","timeoutSeconds":300}
```

Жду результат worker — он придёт отдельным сообщением в этот чат.

